function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  cards.forEach((el, i) => {
    const s = spr(tf, i * 0.45, 0.8, 8);
    el.style.opacity = clamp(s * 2);
    const y = lerp(40, 0, E_OUT(clamp(s)));
    const scale = lerp(0.9, 1, E_OUT(clamp(s)));
    el.style.transform = `translateY(${y}px) scale(${scale})`;
  });

  lines.forEach((line, i) => {
    const s = spr(tf, 0.3 + i * 0.45, 0.8, 8);
    line.el.style.strokeDashoffset = lerp(line.len, 0, clamp(s));
    line.el.style.opacity = clamp(s * 2);
  });

  const ss = spr(tf, 2.0, 0.8, 7);
  stars.style.opacity = clamp(ss * 2);
  stars.style.transform = `translateY(${lerp(20, 0, E_OUT(clamp(ss)))}px)`;

  // Highlight focus during introduction
  if (p < 0.5) {
    cards.forEach((el, i) => {
      const focus = spr(tf - (i * 0.45), 0, 0.7, 6);
      if (focus > 0 && focus < 1) {
        const pulse = 1 + 0.03 * Math.sin(focus * Math.PI);
        const baseTransform = el.style.transform.split(' scale')[0];
        el.style.transform = `${baseTransform} scale(${pulse})`;
      }
    });
  }
}
